'use strict';

const fs = require('node:fs');
const path = require('node:path');

const MAX_LOG_BYTES = 1024 * 1024; // 1 MiB cap to keep app storage bounded
const logFile = process.env.AGY_MODEL_PROXY_LOG || '';
let logDirReady = false;

function formatArgs(args) {
  return args
    .map((arg) => {
      if (typeof arg === 'string') return arg;
      if (arg instanceof Error) return arg.stack || arg.message;
      try {
        return JSON.stringify(arg);
      } catch {
        return String(arg);
      }
    })
    .join(' ');
}

function appendFileLine(line) {
  if (!logFile) return;
  try {
    if (!logDirReady) {
      fs.mkdirSync(path.dirname(logFile), { recursive: true, mode: 0o700 });
      logDirReady = true;
    }
    try {
      const stat = fs.statSync(logFile);
      if (stat.size > MAX_LOG_BYTES) {
        const rotated = `${logFile}.1`;
        try { fs.unlinkSync(rotated); } catch {}
        fs.renameSync(logFile, rotated);
      }
    } catch {}
    fs.appendFileSync(logFile, line + '\n', { encoding: 'utf8', mode: 0o600 });
  } catch {
    // Best-effort file logging; never crash proxy on log failure.
  }
}

function emit(level, args) {
  const ts = new Date().toISOString();
  const text = `${ts} [${level}] ${formatArgs(args)}`;
  if (level === 'ERROR' || level === 'WARN') {
    console.error(text);
  } else {
    console.log(text);
  }
  appendFileLine(text);
}

const logger = {
  info: (...args) => emit('INFO', args),
  warn: (...args) => emit('WARN', args),
  error: (...args) => emit('ERROR', args),
  debug: (...args) => emit('DEBUG', args),
  verbose: (...args) => emit('VERBOSE', args),
  silly: (...args) => emit('SILLY', args),
  log: (...args) => emit('INFO', args),
  transports: {
    file: { level: 'info', fileName: logFile },
    console: { level: 'info' },
  },
  initialize: () => {},
};

logger.default = logger;
module.exports = logger;
